<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import * as api from '../../api/admin'
import type { Schema } from '../../types/api'
import AppDrawer from '../../components/AppDrawer.vue'
import AppDialog from '../../components/AppDialog.vue'
import { useAdminRequest, pretty } from './shared'
const {busy,error,run} = useAdminRequest()
const agents = ref<Schema<'AgentVersion'>[]>([]), specs = ref<Schema<'SpecVersion'>[]>([])
const agentOpen = ref(false), specOpen = ref(false), confirmOpen = ref(false), confirmation = ref<'agent'|'spec'>('agent'), notice=ref('')
const agent = ref<Schema<'AgentDraft'>>(newAgent()), spec = ref<Schema<'SpecDraft'>>(newSpec())
const agentPolicies=ref('{}'), specPolicies=ref('{}'), fields=ref('{}'), combinations=ref('[]'), requiredFields=ref('')
const currentAgent = computed(() => agents.value.find(x=>x.agent_id===agent.value.agent_id))
const currentSpec = computed(() => specs.value.find(x=>x.spec_id===spec.value.spec_id))
function newAgent(): Schema<'AgentDraft'> { return {agent_id:crypto.randomUUID(),version:'',expected_version:null,name:'',kind:'copy',mode:'mock',test_only:true,enabled:false,reason:'',endpoint:'',secret_ref:null,protocol_version:'',policy_versions:{},input_support:{product_required_fields:[],instruction_required:false,min_materials:0,max_materials:0}} }
function newSpec(): Schema<'SpecDraft'> { return {spec_id:crypto.randomUUID(),agent_id:'',agent_version:'',version:'',expected_version:null,name:'',enabled:false,reason:'',delivery_kind:'single',parameter_schema:{fields:{},combinations:[]},policy_versions:{}} }
function load() { return run(() => Promise.all([api.listAgents(),api.listSpecs()]),([a,s])=>{agents.value=a;specs.value=s}) }
function editAgent(row?: Schema<'AgentVersion'>) {
 agent.value=row ? {...JSON.parse(JSON.stringify(row)),expected_version:row.version,version:'',endpoint:'',secret_ref:null,reason:''} : newAgent()
 // Responses deliberately omit endpoint and secret: never substitute redacted values on save.
 const {secret_configured: _unused,...draft}=agent.value as Schema<'AgentDraft'> & {secret_configured?:boolean}; agent.value=draft
 agentPolicies.value=pretty(agent.value.policy_versions); requiredFields.value=agent.value.input_support.product_required_fields.join(', '); error.value='';agentOpen.value=true
}
function editSpec(row?: Schema<'SpecVersion'>) { spec.value=row ? {...JSON.parse(JSON.stringify(row)),expected_version:row.version,version:'',reason:''} : newSpec(); specPolicies.value=pretty(spec.value.policy_versions);fields.value=pretty(spec.value.parameter_schema.fields);combinations.value=pretty(spec.value.parameter_schema.combinations);error.value='';specOpen.value=true }
function prepare(kind:'agent'|'spec') {
 try {
  if(kind==='agent') { agent.value.policy_versions=JSON.parse(agentPolicies.value);agent.value.input_support.product_required_fields=requiredFields.value.split(',').map(x=>x.trim()).filter(Boolean); if(agent.value.enabled && !agent.value.policy_versions['D-03']) throw Error('启用 Agent 需要已确认的 D-03 政策版本。') }
  else { spec.value.policy_versions=JSON.parse(specPolicies.value);spec.value.parameter_schema={fields:JSON.parse(fields.value),combinations:JSON.parse(combinations.value)}; if(spec.value.enabled && !spec.value.policy_versions['D-02']) throw Error('启用规格需要已确认的 D-02 政策版本。') }
  confirmation.value=kind;confirmOpen.value=true;error.value=''
 } catch(e) {error.value=e instanceof SyntaxError ? '字段约束或政策版本 JSON 格式无效，草稿已保留。' : (e as Error).message}
}
async function publish() {
 const ok = confirmation.value==='agent' ? await run(()=>api.saveAgent(JSON.parse(JSON.stringify(agent.value))),()=>{agent.value.endpoint='';agent.value.secret_ref=null;agentOpen.value=false}) : await run(()=>api.saveSpec(JSON.parse(JSON.stringify(spec.value))),()=>{specOpen.value=false})
 if(ok) {confirmOpen.value=false;notice.value='新版本已保存，操作原因进入审计记录。';await load()}
}
onMounted(load)
</script>
<template>
 <div class="admin-page"><header class="page-heading"><h1>Agent 与规格</h1><p>按版本维护输入要求、参数约束和可用范围。</p></header><p v-if="error" class="field-error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><button class="button" :disabled="busy" @click="load">刷新当前版本</button>
 <section class="panel"><div class="section-heading"><h2>Agent</h2><button class="button primary" :disabled="busy" @click="editAgent()">新增 Agent</button></div><div class="admin-table"><table><thead><tr><th>名称</th><th>类型 / 环境</th><th>版本</th><th>状态</th><th>凭据</th><th>操作</th></tr></thead><tbody><tr v-for="row in agents" :key="row.agent_id"><td>{{ row.name }}</td><td>{{ row.kind }} / {{ row.mode }}<small v-if="row.test_only">TEST_ONLY</small></td><td>{{ row.version }}</td><td>{{ row.enabled?'启用':'停用' }}</td><td>{{ row.secret_configured?'已配置（隐藏）':'未配置' }}</td><td><button class="button" :disabled="busy" @click="editAgent(row)">详情与编辑</button></td></tr></tbody></table></div><p v-if="!busy && !agents.length">暂无 Agent 配置。</p></section>
 <section class="panel"><div class="section-heading"><h2>参数规格</h2><button class="button primary" :disabled="busy" @click="editSpec()">新增规格</button></div><div class="admin-table"><table><thead><tr><th>规格</th><th>版本</th><th>绑定 Agent 版本</th><th>交付类型</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in specs" :key="row.spec_id"><td>{{ row.name }}</td><td>{{ row.version }}</td><td>{{ agents.find(a=>a.agent_id===row.agent_id)?.name || row.agent_id }} / {{ row.agent_version }}</td><td>{{ row.delivery_kind }}</td><td>{{ row.enabled?'启用':'停用' }}</td><td><button class="button" :disabled="busy" @click="editSpec(row)">字段与约束</button></td></tr></tbody></table></div><p v-if="!busy && !specs.length">暂无规格。</p></section></div>
 <AppDrawer v-model:open="agentOpen" title="Agent 详情与编辑" purpose="edit"><form id="admin-agent" class="form-stack" @submit.prevent="prepare('agent')"><p>原版本：{{ agent.expected_version || '新建' }}。保存会创建新版本；生产启用由服务端校验已确认政策。</p><label>名称<input v-model="agent.name" data-initial-focus required maxlength="128"></label><label>Agent 标识<input v-model="agent.agent_id" required :readonly="!!agent.expected_version"></label><label>新版本号<input v-model="agent.version" required pattern="[\w.-]+"></label><label>类型<select v-model="agent.kind"><option value="copy">文案</option><option value="image">图片</option><option value="video">视频</option></select></label><label>环境<select v-model="agent.mode"><option value="mock">mock</option><option value="staging">staging</option><option value="production">production</option></select></label><label>仅用于测试<select v-model="agent.test_only"><option :value="true">是</option><option :value="false">否</option></select></label><label>发布后状态<select v-model="agent.enabled"><option :value="false">停用</option><option :value="true">启用（须通过政策门槛）</option></select></label><label>协议版本<input v-model="agent.protocol_version" required></label><label>服务端点（须重新提供）<input v-model="agent.endpoint" type="password" autocomplete="off" required></label><label>凭据引用（非完整密钥）<input v-model="agent.secret_ref" type="password" autocomplete="off"></label><label>商品必填字段（逗号分隔）<input v-model="requiredFields"></label><label>指令必填<select v-model="agent.input_support.instruction_required"><option :value="false">否</option><option :value="true">是</option></select></label><label>最少素材数<input v-model.number="agent.input_support.min_materials" type="number" min="0" required></label><label>最多素材数<input v-model.number="agent.input_support.max_materials" type="number" :min="agent.input_support.min_materials" required></label><label>已确认政策版本（JSON 对象）<textarea v-model="agentPolicies" rows="5" required /></label><label>修改原因<textarea v-model="agent.reason" maxlength="500" required /></label><p v-if="error" class="field-error" role="alert">{{ error }}</p><button class="button" type="button" :disabled="busy" @click="load">核对最新版本（保留草稿）</button><template v-if="currentAgent && currentAgent.version!==agent.expected_version"><p>当前版本 {{ currentAgent.version }}</p><button type="button" class="button" @click="agent.expected_version=currentAgent.version">已核对，采用当前版本</button></template></form><template #actions><button class="button primary" form="admin-agent" :disabled="busy">确认新版本</button></template></AppDrawer>
 <AppDrawer v-model:open="specOpen" title="规格字段与约束" purpose="edit"><form id="admin-spec" class="form-stack" @submit.prevent="prepare('spec')"><p>原版本：{{ spec.expected_version || '新建' }}。D-02 参数能力和多结果政策未确认时不能启用。</p><label>规格名称<input v-model="spec.name" required data-initial-focus></label><label>规格标识<input v-model="spec.spec_id" required :readonly="!!spec.expected_version"></label><label>新版本号<input v-model="spec.version" required pattern="[\w.-]+"></label><label>Agent<select v-model="spec.agent_id" required @change="spec.agent_version=agents.find(x=>x.agent_id===spec.agent_id)?.version || ''"><option value="">选择 Agent</option><option v-for="a in agents" :key="a.agent_id" :value="a.agent_id">{{ a.name }}</option></select></label><label>绑定 Agent 版本<input v-model="spec.agent_version" required></label><label>交付类型<select v-model="spec.delivery_kind"><option value="single">单结果</option><option value="multiple">多个结果</option><option value="detail_images">详情图组</option></select></label><label>字段规则（JSON 对象）<textarea v-model="fields" rows="10" required /></label><small>字段规则包含 kind、required、choices、default 及上下限；沿用服务端 ParameterRule 契约。</small><label>允许组合（JSON 数组）<textarea v-model="combinations" rows="4" required /></label><label>已确认政策版本（JSON 对象）<textarea v-model="specPolicies" rows="5" required /></label><label>发布后状态<select v-model="spec.enabled"><option :value="false">停用</option><option :value="true">启用（须通过政策门槛）</option></select></label><label>修改原因<textarea v-model="spec.reason" required maxlength="500" /></label><p v-if="error" class="field-error" role="alert">{{ error }}</p><button class="button" type="button" :disabled="busy" @click="load">核对最新版本（保留草稿）</button><template v-if="currentSpec && currentSpec.version!==spec.expected_version"><p>当前版本 {{ currentSpec.version }}</p><button type="button" class="button" @click="spec.expected_version=currentSpec.version">已核对，采用当前版本</button></template></form><template #actions><button class="button primary" form="admin-spec" :disabled="busy">确认规格版本</button></template></AppDrawer>
 <AppDialog v-model:open="confirmOpen" title="确认发布配置版本" purpose="delete"><p>将发布{{ confirmation==='agent'?' Agent ':'规格' }} {{ confirmation==='agent'?agent.name:spec.name }} 的新版本，状态为{{ (confirmation==='agent'?agent.enabled:spec.enabled)?'启用':'停用' }}。</p><p>服务端将校验版本及政策门槛，原任务继续使用原快照。</p><p v-if="error" class="field-error" role="alert">{{ error }}</p><template #actions><button class="button danger" :disabled="busy" @click="publish">发布配置版本</button></template></AppDialog>
</template>
